sysevent_script_action.script:
try {
    var id = event.parm1.toString();
    new x_hsb11_mss_tsd.MSS_Treasury_ITM_Utils().sendToITM(id);
} catch (err) {
    gs.error("Script Action Send Treasury Instruction Details to ITM unknown Error:" + err.message);
    new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent("MINOR", "Script Action Send Treasury Instruction Details to ITM unknown Error:" + err.message, 'MSSiQubeSN');
}
